// Rotation automatique des 7 catégories
const categories = [
  { id: 1, name: "Excellence Opérationnelle", emoji: "🔵", keywords: "optimisation, processus, kaizen, lean, performance" },
  { id: 2, name: "Transformation Digitale", emoji: "🟣", keywords: "transformation, digitalisation, modernisation, changement" },
  { id: 3, name: "Intelligence Artificielle & Innovation", emoji: "🔴", keywords: "IA générative, ChatGPT, machine learning, agents autonomes" },
  { id: 4, name: "Finance & IA", emoji: "🟢", keywords: "fintech, finance, comptabilité, analyse financière" },
  { id: 5, name: "Marketing Automation & Data", emoji: "🟠", keywords: "marketing automation, personnalisation, SEO, analytics" },
  { id: 6, name: "RH & Talent Management", emoji: "🔷", keywords: "recrutement, talent, formation, engagement collaborateur" },
  { id: 7, name: "Stratégie & Gouvernance IA", emoji: "⚫", keywords: "stratégie IA, gouvernance, ROI, éthique, diagnostic" }
];

// Rotation basée sur le jour de l'année
const now = new Date();
const start = new Date(now.getFullYear(), 0, 0);
const diff = now - start;
const oneDay = 1000 * 60 * 60 * 24;
const dayOfYear = Math.floor(diff / oneDay);

// Choisir la catégorie (rotation sur 7 jours)
const categoryIndex = dayOfYear % 7;
const selectedCategory = categories[categoryIndex];

return [{
  json: {
    category_id: selectedCategory.id,
    category_name: selectedCategory.name,
    category_emoji: selectedCategory.emoji,
    category_keywords: selectedCategory.keywords,
    execution_time: now.toISOString(),
    day_of_year: dayOfYear
  }
}];

// Préparer le post LinkedIn
const article = $input.item.json;
const wpResponse = $('WordPress: Publish').item.json;

// Texte du post LinkedIn (max 3000 caractères)
const linkedinText = `🚀 ${article.title}

${article.excerpt}

📖 Lire l'article complet : ${wpResponse.link}

${article.keywords.map(k => '#' + k.replace(/\s+/g, '')).join(' ')}

#EazyLink #${article.category_name.replace(/\s+/g, '')} #IA #Innovation #Business`;

return [{
  json: {
    text: linkedinText.substring(0, 3000), // Limite LinkedIn
    article_url: wpResponse.link,
    article_title: article.title,
    category: article.category_name
  }
}];

